package vmcompat;
import java.nio.*;import java.util.*;import org.lwjgl.*;import org.lwjgl.glfw.*;import org.lwjgl.opengl.*;
/** Actual compressed bytes plus decoded pixels; runs only in the existing component harness. */
public final class CompressedCopyTests {
 static void check(boolean b,String s){if(!b)throw new AssertionError(s+" GL="+GL11.glGetError());}
 static int block(int format){return format==0x83F0||format==0x83F1||format==0x8C4C||format==0x8C4D?8:16;}
 static ByteBuffer data(int n,int bytes,int color){ByteBuffer b=BufferUtils.createByteBuffer(n*bytes).order(ByteOrder.LITTLE_ENDIAN);for(int i=0;i<n;i++){if(bytes==16)b.putLong((i&1)==0?255L:0xff00L);int blockColor=i==0?color:switch(i%3){case 0->0xffff;case 1->0x07e0;default->0x001f;};b.putShort((short)blockColor).putShort((short)0).putInt(0);}return b.flip();}
 static int texture(int target,int format,int side,int levels){int t=Textures.glCreateTextures(target);if(target==GL30.GL_TEXTURE_2D_ARRAY)Textures.glTextureStorage3D(t,levels,format,side,side,2);else Textures.glTextureStorage2D(t,levels,format,side,side);Textures.glTextureParameteri(t,GL11.GL_TEXTURE_MIN_FILTER,GL11.GL_NEAREST);Textures.glTextureParameteri(t,GL11.GL_TEXTURE_MAG_FILTER,GL11.GL_NEAREST);return t;}
 static void upload(int texture,int target,int level,int layer,int side,int format,int color){ByteBuffer bytes=data(((side+3)/4)*((side+3)/4),block(format),color);Textures.bound(texture,()->{if(target==GL30.GL_TEXTURE_2D_ARRAY)Textures.glCompressedTexSubImage3D(target,level,0,0,layer,side,side,1,format,bytes);else Textures.glCompressedTexSubImage2D(target==GL13.GL_TEXTURE_CUBE_MAP?GL13.GL_TEXTURE_CUBE_MAP_POSITIVE_X+layer:target,level,0,0,side,side,format,bytes);});check(GL11.glGetError()==0,"upload");}
 static ByteBuffer read(int texture,int target,int level,int layer){int q=target==GL13.GL_TEXTURE_CUBE_MAP?GL13.GL_TEXTURE_CUBE_MAP_POSITIVE_X+layer:target;int[] n={0};Textures.bound(texture,()->n[0]=GL11.glGetTexLevelParameteri(q,level,GL13.GL_TEXTURE_COMPRESSED_IMAGE_SIZE));ByteBuffer b=BufferUtils.createByteBuffer(n[0]);Textures.bound(texture,()->GL13.glGetCompressedTexImage(q,level,b));check(GL11.glGetError()==0,"read compressed");return b;}
 static void same(ByteBuffer a,int offset,ByteBuffer b,int at,int n,String label){for(int i=0;i<n;i++)check(a.get(offset+i)==b.get(at+i),label+" byte "+i+" src="+(a.get(offset+i)&255)+" dst="+(b.get(at+i)&255));}
 static void decoded(int texture,int target,int level,int layer,int side,int expected){int q=target==GL13.GL_TEXTURE_CUBE_MAP?GL13.GL_TEXTURE_CUBE_MAP_POSITIVE_X+layer:target;ByteBuffer b=BufferUtils.createByteBuffer(side*side*4*(target==GL30.GL_TEXTURE_2D_ARRAY?2:1));Textures.bound(texture,()->GL11.glGetTexImage(q,level,GL11.GL_RGBA,GL11.GL_UNSIGNED_BYTE,b));int at=target==GL30.GL_TEXTURE_2D_ARRAY?layer*side*side*4:0;check((b.get(at+expected)&255)>245,"decoded selected colour");check(GL11.glGetError()==0,"decoded pixels");}
 public static void main(String[] args){check(GLFW.glfwInit(),"GLFW");GLFW.glfwWindowHint(GLFW.GLFW_VISIBLE,0);long window=Context.createWindow(32,32,"Exact compressed image-copy checks",0,0);Context.makeCurrent(window);Context.capabilities();int cases=0;
  for(int f:new int[]{0x83F0,0x83F1,0x83F2,0x83F3,0x8C4C,0x8C4D,0x8C4E,0x8C4F})for(int target:new int[]{GL11.GL_TEXTURE_2D,GL30.GL_TEXTURE_2D_ARRAY,GL13.GL_TEXTURE_CUBE_MAP}){
   System.out.println("CASE format="+f+" target="+target);int src=texture(GL11.GL_TEXTURE_2D,f,8,4),dst=texture(target,f,8,4),layer=target==GL11.GL_TEXTURE_2D?0:1;upload(src,GL11.GL_TEXTURE_2D,0,0,8,f,0xf800);Textures.glCopyImageSubData(src,GL11.GL_TEXTURE_2D,0,0,0,0,dst,target,0,0,0,layer,8,8,1);same(read(src,GL11.GL_TEXTURE_2D,0,0),0,read(dst,target,0,layer),target==GL30.GL_TEXTURE_2D_ARRAY?4*block(f):0,4*block(f),"full level");decoded(dst,target,0,layer,8,0);
   long[] stable=CompressedCopies.diagnostics();for(int i=0;i<5;i++)Textures.glCopyImageSubData(src,GL11.GL_TEXTURE_2D,0,0,0,0,dst,target,0,0,0,layer,8,8,1);check(CompressedCopies.diagnostics()[0]==stable[0],"unchanged source not reimported");
   upload(src,GL11.GL_TEXTURE_2D,0,0,8,f,0x07e0);Textures.glCopyImageSubData(src,GL11.GL_TEXTURE_2D,0,4,4,0,dst,target,0,4,0,layer,4,4,1);ByteBuffer expected=read(src,GL11.GL_TEXTURE_2D,0,0),actual=read(dst,target,0,layer);same(expected,3*block(f),actual,(target==GL30.GL_TEXTURE_2D_ARRAY?4*block(f):0)+block(f),block(f),"cropped mutation");
   for(int level=1;level<4;level++){int side=8>>level;upload(src,GL11.GL_TEXTURE_2D,level,0,side,f,0x001f);Textures.glCopyImageSubData(src,GL11.GL_TEXTURE_2D,level,0,0,0,dst,target,level,0,0,layer,side,side,1);same(read(src,GL11.GL_TEXTURE_2D,level,0),0,read(dst,target,level,layer),target==GL30.GL_TEXTURE_2D_ARRAY?block(f):0,block(f),"small mip");decoded(dst,target,level,layer,side,2);}
   if(target!=GL11.GL_TEXTURE_2D){int other=texture(GL11.GL_TEXTURE_2D,f,8,4);Textures.glCopyImageSubData(dst,target,3,0,0,layer,other,GL11.GL_TEXTURE_2D,3,0,0,0,1,1,1);same(read(dst,target,3,layer),target==GL30.GL_TEXTURE_2D_ARRAY?block(f):0,read(other,GL11.GL_TEXTURE_2D,3,0),0,block(f),"reverse target");Textures.glDeleteTextures(other);}
   if(target==GL30.GL_TEXTURE_2D_ARRAY){int view=Textures.glGenTextures();Textures.glTextureView(view,GL11.GL_TEXTURE_2D,dst,f,1,3,1,1);for(int level=0;level<3;level++){same(read(dst,target,level+1,1),block(f),read(view,GL11.GL_TEXTURE_2D,level,0),0,block(f),"view all mips");decoded(view,GL11.GL_TEXTURE_2D,level,0,4>>level,2);}Textures.glDeleteTextures(view);}
   long before=Textures.version(dst);boolean refused=false;try{Textures.glCopyImageSubData(src,GL11.GL_TEXTURE_2D,0,1,0,0,dst,target,0,0,0,layer,4,4,1);}catch(IllegalArgumentException e){refused=true;}check(refused&&Textures.version(dst)==before,"invalid blocks rejected before update");Textures.glDeleteTextures(src);Textures.glDeleteTextures(dst);cases++;
  }
  int src=texture(GL11.GL_TEXTURE_2D,0x83F3,8,1),dst=texture(GL11.GL_TEXTURE_2D,0x83F3,8,1);upload(src,GL11.GL_TEXTURE_2D,0,0,8,0x83F3,0xf800);int[] buffers={Buffers.glGenBuffers(),Buffers.glGenBuffers(),Buffers.glGenBuffers(),Buffers.glGenBuffers()};int[] targets={GL21.GL_PIXEL_PACK_BUFFER,GL21.GL_PIXEL_UNPACK_BUFFER,GL31.GL_COPY_READ_BUFFER,GL31.GL_COPY_WRITE_BUFFER};for(int i=0;i<4;i++){GL15.glBindBuffer(targets[i],buffers[i]);Buffers.glBufferData(targets[i],128,GL15.GL_STREAM_COPY);}GL11.glPixelStorei(GL11.GL_UNPACK_ALIGNMENT,8);GL11.glPixelStorei(GL11.GL_UNPACK_ROW_LENGTH,13);GL11.glPixelStorei(GL12.GL_UNPACK_IMAGE_HEIGHT,17);Textures.glCopyImageSubData(src,GL11.GL_TEXTURE_2D,0,0,0,0,dst,GL11.GL_TEXTURE_2D,0,0,0,0,8,8,1);for(int i=0;i<4;i++)check(GL11.glGetInteger(targets[i]==GL21.GL_PIXEL_PACK_BUFFER?GL21.GL_PIXEL_PACK_BUFFER_BINDING:targets[i]==GL21.GL_PIXEL_UNPACK_BUFFER?GL21.GL_PIXEL_UNPACK_BUFFER_BINDING:targets[i])==buffers[i],"buffer state restored");check(GL11.glGetInteger(GL11.GL_UNPACK_ALIGNMENT)==8&&GL11.glGetInteger(GL11.GL_UNPACK_ROW_LENGTH)==13&&GL11.glGetInteger(GL12.GL_UNPACK_IMAGE_HEIGHT)==17,"pixel store restored");for(int target:targets)GL15.glBindBuffer(target,0);GL11.glPixelStorei(GL11.GL_UNPACK_ALIGNMENT,4);GL11.glPixelStorei(GL11.GL_UNPACK_ROW_LENGTH,0);GL11.glPixelStorei(GL12.GL_UNPACK_IMAGE_HEIGHT,0);Buffers.glDeleteBuffers(buffers);Textures.glDeleteTextures(src);Textures.glDeleteTextures(dst);
  long other=Context.createWindow(16,16,"Inactive compressed cache lifetime",0,0);Context.makeCurrent(other);Context.capabilities();int a=texture(GL11.GL_TEXTURE_2D,0x83F3,8,1),b=texture(GL11.GL_TEXTURE_2D,0x83F3,8,1);upload(a,GL11.GL_TEXTURE_2D,0,0,8,0x83F3,0xf800);Textures.glCopyImageSubData(a,GL11.GL_TEXTURE_2D,0,0,0,0,b,GL11.GL_TEXTURE_2D,0,0,0,0,8,8,1);long extra=CompressedCopies.memory()[0],beforeClose=CompressedCopies.diagnostics()[4];Context.makeCurrent(window);Context.capabilities();Context.destroyWindow(other);check(CompressedCopies.diagnostics()[4]==beforeClose-extra,"inactive context CPU cache released");
  check(CompressedCopies.memory()[0]<=CompressedCopies.SOURCE_LIMIT+CompressedCopies.STRIP_LIMIT,"bounded storage");Context.destroyWindow(window);GLFW.glfwTerminate();check(Packing.memoryStats()[0]==0,"retirement released on context close");System.out.println("PASS "+cases+" compressed format/target cases, exact blocks and decoded pixels, cache, mutation, mips, crop, reverse copies, rejection and state restoration");
 }
}
